// Fehlalarm-Sammlung für lieferkette/*: typische harmlose Abhängigkeits-Updates, nachgebaut in der Form,
// die Dependabot, Renovate und die Paketmanager selbst erzeugen. Alle Namen und Adressen sind erfunden.
// Erwartung: kein Befund mit warn oder block (ein Hinweis „lock-ohne-manifest“ ist bei Lockfile-only-Updates erlaubt).
import { aenderung, json, npmLock, reg, integ } from '../../lieferkette-hilfen.mjs';

const manifest = (deps, dev = {}, extra = {}) => json({ name: 'beispiel-app', version: '1.0.0', private: true, scripts: { test: 'node --test', build: 'tsc -p .' }, dependencies: deps, devDependencies: dev, ...extra });
const eintrag = (name, version, z, extra = {}) => ({ [`node_modules/${name}`]: { version, resolved: reg(name, version), integrity: integ(z), ...extra } });

const D0 = { 'kern-lib': '^1.2.0', 'hilfs-werk': '^3.0.0', 'datum-zeit': '^2.1.0' };
const L0 = { ...eintrag('kern-lib', '1.2.0', 'A'), ...eintrag('hilfs-werk', '3.0.0', 'B'), ...eintrag('datum-zeit', '2.1.0', 'C'), ...eintrag('bau-werk', '0.9.0', 'D', { dev: true, hasInstallScript: true }) };

const yarnV1 = (eintraege) => '# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n# yarn lockfile v1\n\n\n' + eintraege.map(([spec, ver, z]) => {
  const name = spec.slice(0, spec.indexOf('@', 1));
  return `${spec}:\n  version "${ver}"\n  resolved "https://registry.yarnpkg.com/${name}/-/${name.split('/').pop()}-${ver}.tgz#${z.repeat(40).slice(0, 40)}"\n  integrity ${integ(z)}\n`;
}).join('\n');

const pnpm = (pakete) => `lockfileVersion: '9.0'\n\nsettings:\n  autoInstallPeers: true\n\nimporters:\n\n  .:\n    dependencies:\n${pakete.map(([n, v]) => `      ${n}:\n        specifier: ^${v}\n        version: ${v}\n`).join('')}\npackages:\n\n${pakete.map(([n, v, z, bau]) => `  ${n}@${v}:\n    resolution: {integrity: ${integ(z)}}\n    engines: {node: '>=18'}\n${bau ? '    requiresBuild: true\n' : ''}`).join('\n')}\nsnapshots:\n\n${pakete.map(([n, v]) => `  ${n}@${v}: {}\n`).join('\n')}`;

export const HARMLOS = [
  {
    name: 'Dependabot: Versionssprung mit Lockfile',
    dateien: [
      aenderung('package.json', manifest(D0), manifest({ ...D0, 'kern-lib': '^1.3.0' })),
      aenderung('package-lock.json', npmLock(L0), npmLock({ ...L0, ...eintrag('kern-lib', '1.3.0', 'E') })),
    ],
  },
  {
    name: 'Renovate: Dev-Abhängigkeit mit Install-Skript wird aktualisiert (Skript war schon da)',
    dateien: [
      aenderung('package.json', manifest(D0, { 'bau-werk': '^0.9.0' }), manifest(D0, { 'bau-werk': '^0.10.0' })),
      aenderung('package-lock.json', npmLock(L0), npmLock({ ...L0, ...eintrag('bau-werk', '0.10.0', 'F', { dev: true, hasInstallScript: true }) })),
    ],
  },
  {
    name: 'Neues normales Paket aus der Registry',
    dateien: [
      aenderung('package.json', manifest(D0), manifest({ ...D0, 'farb-palette': '^4.0.0' })),
      aenderung('package-lock.json', npmLock(L0), npmLock({ ...L0, ...eintrag('farb-palette', '4.0.0', 'G') })),
    ],
  },
  {
    name: 'Sicherheitsupdate nur im Lockfile (transitive Abhängigkeit)',
    erlaubt: ['lieferkette/lock-ohne-manifest'],
    dateien: [aenderung('package-lock.json', npmLock(L0), npmLock({ ...L0, ...eintrag('datum-zeit', '2.1.1', 'H') }))],
  },
  {
    name: 'Lockfile-Neuaufbau: Einträge neu sortiert, gleiche Versionen und Integrität',
    erlaubt: ['lieferkette/lock-ohne-manifest'],
    dateien: [aenderung('package-lock.json', npmLock(L0), npmLock(Object.fromEntries(Object.entries(L0).reverse())))],
  },
  {
    name: 'Wechsel der Lockfile-Version 2 → 3',
    dateien: [aenderung('package-lock.json', npmLock(L0, { lockfileVersion: 2 }), npmLock(L0, { lockfileVersion: 3 }))],
  },
  {
    name: 'Integrität von sha1 auf sha512 hochgestuft (alter Lockfile-Stand)',
    erlaubt: ['lieferkette/lock-ohne-manifest'],
    dateien: [aenderung('package-lock.json',
      npmLock({ ...L0, 'node_modules/kern-lib': { version: '1.2.0', resolved: reg('kern-lib', '1.2.0'), integrity: integ('a', 'sha1') } }),
      npmLock(L0))],
  },
  {
    name: 'Workspace-Verweis: neues Paket im Monorepo',
    dateien: [
      aenderung('package.json', manifest(D0, {}, { workspaces: ['packages/*'] }), manifest({ ...D0, '@bsp/ui': 'workspace:*', '@bsp/werkzeug': 'file:./packages/werkzeug' }, {}, { workspaces: ['packages/*'] })),
      aenderung('package-lock.json', npmLock(L0), npmLock({ ...L0, 'node_modules/@bsp/ui': { resolved: 'packages/ui', link: true }, 'node_modules/@bsp/werkzeug': { resolved: 'packages/werkzeug', link: true } })),
    ],
  },
  {
    name: 'Workspace-Paket verweist mit ../ auf ein Geschwister im Repo',
    dateien: [aenderung('packages/app/package.json', manifest({ 'kern-lib': '^1.2.0' }), manifest({ 'kern-lib': '^1.2.0', '@bsp/ui': 'file:../ui' }))],
  },
  {
    name: 'npm-Alias und Distributions-Tag',
    dateien: [aenderung('package.json', manifest(D0), manifest({ ...D0, 'kern-alt': 'npm:kern-lib@^1.0.0', 'nacht-bau': 'latest', 'bereich-lib': '>=1.0.0 <2.0.0' }))],
  },
  {
    name: 'yarn v1: Versionssprung, Bereich zusammengeführt',
    dateien: [
      aenderung('package.json', manifest({ 'kern-lib': '^1.2.0' }), manifest({ 'kern-lib': '^1.3.0' })),
      aenderung('yarn.lock', yarnV1([['kern-lib@^1.2.0', '1.2.0', 'a'], ['hilfs-werk@^3.0.0', '3.0.0', 'b']]), yarnV1([['kern-lib@^1.3.0', '1.3.0', 'c'], ['hilfs-werk@^3.0.0', '3.0.0', 'b']])),
    ],
  },
  {
    name: 'pnpm v9: Versionssprung eines Pakets mit Build-Skript (war schon da)',
    dateien: [
      aenderung('package.json', manifest({ 'kern-lib': '^1.2.0', 'bau-werk': '^0.9.0' }), manifest({ 'kern-lib': '^1.2.0', 'bau-werk': '^0.10.0' })),
      aenderung('pnpm-lock.yaml', pnpm([['kern-lib', '1.2.0', 'a'], ['bau-werk', '0.9.0', 'b', true]]), pnpm([['kern-lib', '1.2.0', 'a'], ['bau-werk', '0.10.0', 'c', true]])),
    ],
  },
  {
    name: 'Typische Namensnachbarn: @types, Plugin-Suffix, Endbuchstabe',
    dateien: [aenderung('package.json', manifest({ 'kern-lib': '^1.0.0', zustand: '^1.0.0', 'bild-werk': '^1.0.0' }), manifest({ 'kern-lib': '^1.0.0', zustand: '^1.0.0', 'bild-werk': '^1.0.0', '@types/kern-lib': '^1.0.0', zustandx: '^1.0.0', 'bild-werk-plugin': '^1.0.0' }))],
  },
  {
    name: '.npmrc: Einstellungen ohne Registry (engine-strict, save-exact, Token aus der Umgebung)',
    dateien: [aenderung('.npmrc', 'engine-strict=true\n', 'engine-strict=true\nsave-exact=true\nfund=false\n//registry.npmjs.org/:_authToken=${NPM_TOKEN}\n')],
  },
  {
    name: 'Release: Version im Manifest und im Lockfile-Kopf',
    dateien: [
      aenderung('package.json', manifest(D0), manifest(D0).replace('"version": "1.0.0"', '"version": "1.1.0"')),
      aenderung('package-lock.json', npmLock(L0), npmLock(L0).replaceAll('"version": "1.0.0"', '"version": "1.1.0"')),
    ],
  },
  {
    name: 'Abhängigkeit entfernt',
    dateien: [
      aenderung('package.json', manifest(D0), manifest({ 'kern-lib': '^1.2.0', 'hilfs-werk': '^3.0.0' })),
      aenderung('package-lock.json', npmLock(L0), npmLock(Object.fromEntries(Object.entries(L0).filter(([k]) => !k.endsWith('datum-zeit'))))),
    ],
  },
];
